app.post('/api/security/mfa/enable',auth,async(req,res)=>{const row=(await q('SELECT secret_encrypted FROM mfa_credentials WHERE user_id=$1',[req.user.id]))[0];if(!row)return res.status(404).json({error:'Start MFA setup first'});if(!verifyTotp(decryptSecret(row.secret_encrypted),req.body?.code))return res.status(400).json({error:'Invalid authenticator code'});await pool.query('UPDATE mfa_credentials SET enabled_at=now(),updated_at=now() WHERE user_id=$1',[req.user.id]);await pool.query('UPDATE users SET mfa_enabled=true,updated_at=now() WHERE id=$1',[req.user.id]);await audit(req.user,'MFA_ENABLED','Security',req.user.id,'Enabled multi-factor authentication',null,{enabled:true},req.req);res.json({enabled:true})});
