app.get('/api/catalog/products',auth,need('catalog.view'),async(req,res)=>{const limit=Math.min(Math.max(Number(req.query.limit)||25,1),100);const offset=Math.max(Number(req.query.offset)||0,0);const params=[];const where=[];const text=String(req.query.q||'').trim();if(text){params.push(`%${text}%`);where.push(`(p.name ILIKE $${params.length} OR p.slug ILIKE $${params.length} OR COALESCE(b.name,'') ILIKE $${params.length} OR EXISTS(SELECT 1 FROM product_variants vv WHERE vv.product_id=p.id AND vv.sku ILIKE $${params.length}))`)}if(req.query.brandId){params.push(req.query.brandId);where.push(`p.brand_id=$${params.length}`)}if(req.query.categoryId){params.push(req.query.categoryId);where.push(`p.category_id=$${params.length}`)}if(req.query.status){params.push(req.query.status);where.push(`p.status=$${params.length}`)}if(req.query.visibility){params.push(req.query.visibility);where.push(`p.website_visibility=$${params.length}`)}const countParams=[...params];const whereSql=where.length?'WHERE '+where.join(' AND '):'';const count=(await q(`SELECT count(*)::int c FROM products p LEFT JOIN brands b ON b.id=p.brand_id ${whereSql}`,countParams))[0].c;params.push(limit,offset);const rows=await q(`SELECT p.id,p.name,p.slug,p.product_type,p.status,p.website_visibility,p.featured,p.updated_at,b.name brand_name,c.name category_name,(SELECT count(*) FROM product_variants v WHERE v.product_id=p.id)::int variant_count,(SELECT min(v.selling_price) FROM product_variants v WHERE v.product_id=p.id AND v.status='Active') min_price,(SELECT max(v.selling_price) FROM product_variants v WHERE v.product_id=p.id AND v.status='Active') max_price,(SELECT i.url FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_primary DESC,i.sort_order,i.created_at LIMIT 1) image_url FROM products p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN product_categories c ON c.id=p.category_id ${whereSql} ORDER BY p.updated_at DESC LIMIT $${params.length-1} OFFSET $${params.length}`,params);res.json({rows,total:count,limit,offset})});
