app.patch('/api/inventory/locations/:id',auth,need('inventory.manage'),async(req,res)=>{const old=(await q('SELECT * FROM inventory_locations WHERE id=$1',[req.params.id]))[0];if(!old)return res.status(404).json({error:'Location not found'});const b=req.body||{};const l=(await q('UPDATE inventory_locations SET name=COALESCE($1,name),code=COALESCE($2,code),type=COALESCE($3,type),address=COALESCE($4,address),notes=COALESCE($5,notes),status=COALESCE($6,status),updated_at=now() WHERE id=$7 RETURNING *',[b.name,b.code?String(b.code).toUpperCase():undefined,b.type,b.address,b.notes,b.status,req.params.id]))[0];await audit(req.user,'INVENTORY_LOCATION_UPDATED','InventoryLocation',l.id,'Updated inventory location',old,l,req.req);res.json(l)});
app.get('/api/inventory/stock',auth,need('inventory.view'),async(req,res)=>{const limit=Math.min(Math.max(Number(req.query.limit)||50,1),200);const offset=Math.max(Number(req.query.offset)||0,0);const params=[];const w=[];if(req.query.q){params.push(`%${String(req.query.q).trim()}%`);w.push(`(v.sku ILIKE $${params.length} OR v.variant_name ILIKE $${params.length} OR p.name ILIKE $${params.length} OR COALESCE(b.name,'') ILIKE $${params.length})`)}if(req.query.locationId){params.push(req.query.locationId);w.push(`ib.location_id=$${params.length}`)}if(req.query.low==='true')w.push('ib.on_hand-ib.reserved<=5 AND ib.on_hand>0');const where=w.length?'WHERE '+w.join(' AND '):'';const count=(await q(`SELECT count(*)::int c FROM inventory_balances ib JOIN product_variants v ON v.id=ib.variant_id JOIN products p ON p.id=v.product_id LEFT JOIN brands b ON b.id=p.brand_id ${where}`,params))[0].c;params.push(limit,offset);const rows=await q(`SELECT ib.id,ib.variant_id,ib.location_id,ib.on_hand,ib.reserved,(ib.on_hand-ib.reserved) available,ib.updated_at,v.sku,v.variant_name,v.serialized,v.cost_price,v.selling_price,p.name product_name,b.name brand_name,l.name location_name FROM inventory_balances ib JOIN product_variants v ON v.id=ib.variant_id JOIN products p ON p.id=v.product_id LEFT JOIN brands b ON b.id=p.brand_id JOIN inventory_locations l ON l.id=ib.location_id ${where} ORDER BY ib.updated_at DESC LIMIT $${params.length-1} OFFSET $${params.length}`,params);res.json({rows,total:count,limit,offset})});
app.get('/api/inventory/movements',auth,need('inventory.view'),async(req,res)=>{const limit=Math.min(Number(req.query.limit)||100,500);res.json(await q(`SELECT m.*,v.sku,v.variant_name,p.name product_name,l.name location_name,u.email actor_email FROM inventory_movements m JOIN product_variants v ON v.id=m.variant_id JOIN products p ON p.id=v.product_id JOIN inventory_locations l ON l.id=m.location_id LEFT JOIN users u ON u.id=m.actor_id ORDER BY m.created_at DESC LIMIT $1`,[limit]))});
app.post('/api/inventory/receipts',auth,need('inventory.receive'),async(req,res)=>{const b=req.body||{};if(!b.locationId||!Array.isArray(b.lines)||!b.lines.length)return res.status(400).json({error:'Location and at least one receipt line are required'});const client=await pool.connect();try{await client.query('BEGIN');const receipt=(await client.query('INSERT INTO stock_receipts(receipt_no,location_id,supplier_name,supplier_reference,notes,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[inventoryNo('GRN'),b.locationId,String(b.supplierName||''),String(b.supplierReference||''),String(b.notes||''),req.user.id])).rows[0];for(const line of b.lines){const qty=Number(line.quantity);if(!(qty>0))throw new Error('Receipt quantity must be greater than zero');const variant=(await client.query('SELECT * FROM product_variants WHERE id=$1',[line.variantId])).rows[0];if(!variant)throw new Error('Variant not found');const serials=Array.isArray(line.serials)?line.serials:[];if(variant.serialized && serials.length!==qty)throw new Error(`Serialized SKU ${variant.sku} requires exactly ${qty} serial/IMEI records`);const rl=(await client.query('INSERT INTO stock_receipt_lines(receipt_id,variant_id,quantity,unit_cost,serials) VALUES($1,$2,$3,$4,$5) RETURNING *',[receipt.id,variant.id,qty,Number(line.unitCost??variant.cost_price),JSON.stringify(serials)])).rows[0];await changeStock(client,{variantId:variant.id,locationId:b.locationId,delta:qty,type:'RECEIPT',actorId:req.user.id,referenceType:'StockReceipt',referenceId:receipt.id,reason:`Goods receipt ${receipt.receipt_no}`,unitCost:Number(line.unitCost??variant.cost_price)});for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;await client.query('INSERT INTO serialized_units(variant_id,location_id,serial_number,imei1,imei2,status,unit_cost,received_at) VALUES($1,$2,$3,$4,$5,\'In Stock\',$6,now())',[variant.id,b.locationId,x.serialNumber||null,x.imei1||null,x.imei2||null,Number(line.unitCost??variant.cost_price)])}}
await client.query('COMMIT');await audit(req.user,'STOCK_RECEIVED','StockReceipt',receipt.id,`Received stock ${receipt.receipt_no}`,null,receipt,req.req);res.status(201).json(receipt)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/receipts',auth,need('inventory.view'),async(req,res)=>res.json(await q(`SELECT r.*,l.name location_name,COUNT(rl.id)::int line_count,COALESCE(SUM(rl.quantity),0)::numeric units FROM stock_receipts r JOIN inventory_locations l ON l.id=r.location_id LEFT JOIN stock_receipt_lines rl ON rl.receipt_id=r.id GROUP BY r.id,l.name ORDER BY r.created_at DESC LIMIT 200`)));
app.post('/api/inventory/adjustments',auth,need('inventory.adjust'),async(req,res)=>{const b=req.body||{};if(!b.locationId||!String(b.reason||'').trim()||!Array.isArray(b.lines)||!b.lines.length)return res.status(400).json({error:'Location, reason and adjustment lines are required'});const client=await pool.connect();try{await client.query('BEGIN');const a=(await client.query('INSERT INTO stock_adjustments(adjustment_no,location_id,reason,created_by) VALUES($1,$2,$3,$4) RETURNING *',[inventoryNo('ADJ'),b.locationId,String(b.reason).trim(),req.user.id])).rows[0];for(const line of b.lines){const delta=Number(line.quantityChange);if(!delta)throw new Error('Adjustment quantity cannot be zero');const variant=(await client.query('SELECT * FROM product_variants WHERE id=$1',[line.variantId])).rows[0];if(!variant)throw new Error('Variant not found');await client.query('INSERT INTO stock_adjustment_lines(adjustment_id,variant_id,quantity_change,unit_cost,reason) VALUES($1,$2,$3,$4,$5)',[a.id,variant.id,delta,line.unitCost==null?variant.cost_price:Number(line.unitCost),String(line.reason||b.reason)]);await changeStock(client,{variantId:variant.id,locationId:b.locationId,delta,type:delta>0?'ADJUSTMENT_IN':'ADJUSTMENT_OUT',actorId:req.user.id,referenceType:'StockAdjustment',referenceId:a.id,reason:String(line.reason||b.reason),unitCost:Number(line.unitCost??variant.cost_price)})}await client.query('COMMIT');await audit(req.user,'STOCK_ADJUSTED','StockAdjustment',a.id,`Applied stock adjustment ${a.adjustment_no}`,null,a,req.req);res.status(201).json(a)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/adjustments',auth,need('inventory.view'),async(req,res)=>res.json(await q(`SELECT a.*,l.name location_name,COUNT(al.id)::int line_count,COALESCE(SUM(al.quantity_change),0)::numeric net_change FROM stock_adjustments a JOIN inventory_locations l ON l.id=a.location_id LEFT JOIN stock_adjustment_lines al ON al.adjustment_id=a.id GROUP BY a.id,l.name ORDER BY a.created_at DESC LIMIT 200`)));
app.post('/api/inventory/transfers',auth,need('inventory.transfer'),async(req,res)=>{const b=req.body||{};if(!b.fromLocationId||!b.toLocationId||b.fromLocationId===b.toLocationId||!Array.isArray(b.lines)||!b.lines.length)return res.status(400).json({error:'Two different locations and at least one transfer line are required'});const client=await pool.connect();try{await client.query('BEGIN');const t=(await client.query('INSERT INTO stock_transfers(transfer_no,from_location_id,to_location_id,notes,requested_by,status) VALUES($1,$2,$3,$4,$5,\'Submitted\') RETURNING *',[inventoryNo('TRF'),b.fromLocationId,b.toLocationId,String(b.notes||''),req.user.id])).rows[0];for(const line of b.lines){const qty=Number(line.quantity);if(!(qty>0))throw new Error('Transfer quantity must be greater than zero');const v=(await client.query('SELECT * FROM product_variants WHERE id=$1',[line.variantId])).rows[0];if(!v)throw new Error('Variant not found');const serials=Array.isArray(line.serials)?line.serials:[];if(v.serialized&&serials.length!==qty)throw new Error(`Serialized SKU ${v.sku} requires exactly ${qty} serial/IMEI records`);await client.query('INSERT INTO stock_transfer_lines(transfer_id,variant_id,quantity,unit_cost,serials) VALUES($1,$2,$3,$4,$5)',[t.id,v.id,qty,Number(line.unitCost??v.cost_price),JSON.stringify(serials)])}await client.query('COMMIT');await audit(req.user,'STOCK_TRANSFER_CREATED','StockTransfer',t.id,`Created transfer ${t.transfer_no}`,null,t,req.req);res.status(201).json(t)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/transfers',auth,need('inventory.view'),async(req,res)=>res.json(await q(`SELECT t.*,fl.name from_location_name,tl.name to_location_name,COUNT(l.id)::int line_count,COALESCE(SUM(l.quantity),0)::numeric units FROM stock_transfers t JOIN inventory_locations fl ON fl.id=t.from_location_id JOIN inventory_locations tl ON tl.id=t.to_location_id LEFT JOIN stock_transfer_lines l ON l.transfer_id=t.id GROUP BY t.id,fl.name,tl.name ORDER BY t.created_at DESC LIMIT 200`)));
app.patch('/api/inventory/transfers/:id/approve',auth,need('inventory.transfer'),async(req,res)=>{const t=(await q("SELECT * FROM stock_transfers WHERE id=$1 AND status='Submitted'",[req.params.id]))[0];if(!t)return res.status(404).json({error:'Submitted transfer not found'});const r=(await q("UPDATE stock_transfers SET status='Approved',approved_by=$1,updated_at=now() WHERE id=$2 RETURNING *",[req.user.id,t.id]))[0];await audit(req.user,'STOCK_TRANSFER_APPROVED','StockTransfer',r.id,'Approved stock transfer',t,r,req.req);res.json(r)});
app.patch('/api/inventory/transfers/:id/ship',auth,need('inventory.transfer'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const t=(await client.query("SELECT * FROM stock_transfers WHERE id=$1 AND status IN ('Approved','Submitted') FOR UPDATE",[req.params.id])).rows[0];if(!t)throw new Error('Transfer is not ready to ship');const lines=(await client.query('SELECT * FROM stock_transfer_lines WHERE transfer_id=$1',[t.id])).rows;for(const line of lines){await changeStock(client,{variantId:line.variant_id,locationId:t.from_location_id,delta:-Number(line.quantity),type:'TRANSFER_OUT',actorId:req.user.id,referenceType:'StockTransfer',referenceId:t.id,reason:`Transfer ${t.transfer_no}`});if(Array.isArray(line.serials)&&line.serials.length){for(const sn of line.serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;const su=(await client.query('UPDATE serialized_units SET status=\'Transferred\',location_id=NULL,updated_at=now() WHERE variant_id=$1 AND (serial_number=$2 OR imei1=$3 OR imei2=$4) RETURNING *',[line.variant_id,x.serialNumber||'',x.imei1||'',x.imei2||''])).rows[0];if(!su)throw new Error('Serialized unit not found for transfer')}}}const r=(await client.query("UPDATE stock_transfers SET status='Shipped',shipped_at=now(),updated_at=now() WHERE id=$1 RETURNING *",[t.id])).rows[0];await client.query('COMMIT');await audit(req.user,'STOCK_TRANSFER_SHIPPED','StockTransfer',r.id,'Shipped stock transfer',t,r,req.req);res.json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.patch('/api/inventory/transfers/:id/receive',auth,need('inventory.transfer'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const t=(await client.query("SELECT * FROM stock_transfers WHERE id=$1 AND status='Shipped' FOR UPDATE",[req.params.id])).rows[0];if(!t)throw new Error('Shipped transfer not found');const lines=(await client.query('SELECT * FROM stock_transfer_lines WHERE transfer_id=$1',[t.id])).rows;for(const line of lines){await changeStock(client,{variantId:line.variant_id,locationId:t.to_location_id,delta:Number(line.quantity),type:'TRANSFER_IN',actorId:req.user.id,referenceType:'StockTransfer',referenceId:t.id,reason:`Transfer ${t.transfer_no}`,unitCost:line.unit_cost});for(const sn of (Array.isArray(line.serials)?line.serials:[])){const x=typeof sn==='string'?{serialNumber:sn}:sn;const su=(await client.query('UPDATE serialized_units SET status=\'In Stock\',location_id=$1,updated_at=now() WHERE variant_id=$2 AND (serial_number=$3 OR imei1=$4 OR imei2=$5) RETURNING *',[t.to_location_id,line.variant_id,x.serialNumber||'',x.imei1||'',x.imei2||''])).rows[0];if(!su){await client.query('INSERT INTO serialized_units(variant_id,location_id,serial_number,imei1,imei2,status,unit_cost,received_at) VALUES($1,$2,$3,$4,$5,\'In Stock\',$6,now())',[line.variant_id,t.to_location_id,x.serialNumber||null,x.imei1||null,x.imei2||null,Number(line.unit_cost||0)])}}}const r=(await client.query("UPDATE stock_transfers SET status='Received',received_at=now(),updated_at=now() WHERE id=$1 RETURNING *",[t.id])).rows[0];await client.query('COMMIT');await audit(req.user,'STOCK_TRANSFER_RECEIVED','StockTransfer',r.id,'Received stock transfer',t,r,req.req);res.json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/inventory/reservations',auth,need('inventory.reserve'),async(req,res)=>{const b=req.body||{};if(!b.variantId||!b.locationId||!(Number(b.quantity)>0))return res.status(400).json({error:'Variant, location and positive quantity are required'});const client=await pool.connect();try{await client.query('BEGIN');const r=await reserveStock(client,{variantId:b.variantId,locationId:b.locationId,quantity:Number(b.quantity),actorId:req.user.id,referenceType:b.referenceType||null,referenceId:b.referenceId||null,expiresAt:b.expiresAt||null});await client.query('COMMIT');await audit(req.user,'STOCK_RESERVED','InventoryReservation',r.id,'Reserved stock',null,r,req.req);res.status(201).json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/reservations',auth,need('inventory.view'),async(req,res)=>res.json(await q(`SELECT r.*,v.sku,v.variant_name,p.name product_name,l.name location_name FROM inventory_reservations r JOIN product_variants v ON v.id=r.variant_id JOIN products p ON p.id=v.product_id JOIN inventory_locations l ON l.id=r.location_id ORDER BY r.created_at DESC LIMIT 200`)));
app.patch('/api/inventory/reservations/:id/release',auth,need('inventory.reserve'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const r=await releaseReservation(client,req.params.id,req.user.id,'Released');await client.query('COMMIT');await audit(req.user,'STOCK_RESERVATION_RELEASED','InventoryReservation',r.id,'Released stock reservation',null,r,req.req);res.json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/serialized',auth,need('inventory.serialized'),async(req,res)=>{const limit=Math.min(Number(req.query.limit)||200,500);res.json(await q(`SELECT s.*,v.sku,v.variant_name,p.name product_name,l.name location_name FROM serialized_units s JOIN product_variants v ON v.id=s.variant_id JOIN products p ON p.id=v.product_id LEFT JOIN inventory_locations l ON l.id=s.location_id ORDER BY s.created_at DESC LIMIT $1`,[limit]))});
app.get('/api/inventory/export',auth,need('inventory.export'),async(req,res)=>{const rows=await q(`SELECT p.name product,v.sku,v.variant_name,l.name location,ib.on_hand,ib.reserved,(ib.on_hand-ib.reserved) available,v.cost_price,v.selling_price FROM inventory_balances ib JOIN product_variants v ON v.id=ib.variant_id JOIN products p ON p.id=v.product_id JOIN inventory_locations l ON l.id=ib.location_id ORDER BY p.name,v.sku,l.name`);const esc=v=>{const x=String(v??'');return /[",\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x};const csv=['product,sku,variant,location,on_hand,reserved,available,cost_price,selling_price',...rows.map(r=>[r.product,r.sku,r.variant_name,r.location,r.on_hand,r.reserved,r.available,r.cost_price,r.selling_price].map(esc).join(','))].join('\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename=amaal-inventory-export.csv');res.send(csv)});

app.use('/api', (err, req, res, next) => {
  console.error('API error:', err);
  if(res.headersSent) return next(err);
  const status=Number(err.status||err.statusCode)||500;
  res.status(status).json({error:status>=500?'Internal server error':String(err.message||'Request failed')});
});

